class ScenesCancelled(Exception):
    """A scene's encoder was ended by Stop now (audit #13)."""


class _SplitProcs:
    """``subprocess`` as _split_video's scene workers see it (audit #13, user
    2026-09-29): run() is v1's subprocess.run, except that the engine's
    ``abort_now`` ends the encoder -- Stop now cancels the scenes being cut
    and discards their .part. ``abort_flag`` alone (Stop after these scenes)
    lets them finish. A check's stand-in for subprocess.run is honoured."""

    def __init__(self, engine):
        self._engine = engine

    def __getattr__(self, name):
        return getattr(subprocess, name)

    def run(self, cmd, *, capture_output=False, text=False, check=False, timeout=None, **kw):
        if getattr(subprocess.run, "__module__", "subprocess") != "subprocess":  # a stand-in
            return subprocess.run(cmd, capture_output=capture_output, text=text, check=check, timeout=timeout, **kw)
        pipe = subprocess.PIPE if capture_output else None
        proc = subprocess.Popen(cmd, stdout=pipe, stderr=pipe, text=text, **kw)
        waited = 0.0
        while True:
            try:
                out, err = proc.communicate(timeout=0.25)
                break
            except subprocess.TimeoutExpired:
                waited += 0.25
                now = getattr(self._engine, "abort_now", None)
                if (now is not None and now.is_set()) or (timeout is not None and waited >= timeout):
                    proc.kill()
                    proc.communicate()
                    last = str(cmd[-1]) if cmd else ""
                    if is_part(last):
                        discard(last)
                    if timeout is not None and waited >= timeout and not (now is not None and now.is_set()):
                        raise subprocess.TimeoutExpired(cmd, timeout)
                    raise ScenesCancelled("stopped: " + os.path.basename(last))
        result = subprocess.CompletedProcess(cmd, proc.returncode, out, err)
        if check:
            result.check_returncode()
        return result


class _Var:
    """A tk variable over one key of the engine's settings dict."""

    def __init__(self, values, key):
        self._values = values
        self._key = key

    def get(self):
        return self._values.get(self._key)

    def set(self, value):
        self._values[self._key] = value


class _Widget:
    """A widget v1 configures from Start / the queue drain: the hooks hear it."""

    def __init__(self, hooks, name):
        self._hooks = hooks
        self._name = name
        self._items = {}

    def configure(self, **kw):
        self._hooks.widget(self._name, dict(kw))

    config = configure

    def __setitem__(self, key, value):
        self._items[key] = value
        self._hooks.widget(self._name, {key: value})

    def __getitem__(self, key):
        return self._items.get(key)


class _MessageBoxShim:
    """v1's tkinter.messagebox, as prompts in the page."""

    def __init__(self):
        self.hooks = None
        self.answer = False

    def _send(self, kind, title, message):
        if self.hooks is not None:
            self.hooks.message(kind, str(title), str(message))
        else:
            logger.warning("%s: %s", title, message)

    def showerror(self, title="", message="", **_kw):
        self._send("error", title, message)

    def showwarning(self, title="", message="", **_kw):
        self._send("warning", title, message)

    def showinfo(self, title="", message="", **_kw):
        self._send("info", title, message)

    def askyesno(self, title="", message="", **_kw):
        return bool(self.answer)


messagebox = _MessageBoxShim()


